def dequeue():
    raw = _QUEUE.get()
    return pickle.loads(raw)  # worker/queue.py:28-29；文档字符串亦自述“pickle.loads 直接反序列化队列里的数据……执行任意代码（RCE）”

def run_once():
    task = dequeue()
    log_task(task)
    try:
        return execute(task)
    except Exception as exc:
        logger.warning("任务执行失败：%s", exc)  # 无 re-raise、无 set_status(..., "failed")

findings.suggestion:
引入最大重试次数与指数退避，并让 should_retry 真正生效，例如：

import time

MAX_ATTEMPTS = 5
BACKOFF_BASE = 0.5

while attempts < MAX_ATTEMPTS:
    try:
        return handler(task)
    except Exception:
        attempts += 1
        if not should_retry(attempts):
            raise
        time.sleep(BACKOFF_BASE * 2 ** attempts + random.uniform(0, 0.1))

同时把 should_retry 改为 return attempts < MAX_ATTEMPTS。

