def run_with_retry(task, handler):
    while True:
        try:
            return handler(task)
        except Exception:
            continue   # worker/retry.py:21-25

# 另一处 weak 实现：
def should_retry(attempts):
    return attempts >= 0   # worker/retry.py:12，恒为 True

findings.suggestion:
只记录非敏感的必要字段，并做脱敏，例如：

SENSITIVE_KEYS = {"password", "token", "secret", "authorization"}

def log_task(task):
    safe = {k: v for k, v in task.items() if k not in SENSITIVE_KEYS and k != "handler"}
    logger.info("开始处理任务 id=%s type=%s payload=%s", task.get("id"), task.get("handler"), safe)

或在日志层配置脱敏过滤器，禁止直接以 %s 输出整个对象。
